{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy grants overly permissive access with wildcard (*)",
      "resource": "aws_iam_policy.fn1-passrole-star",
      "severity": "HIGH",
      "explanation": "The IAM policy attached to the user allows overly permissive access with a wildcard (*) in the policy ARN. This can lead to privilege escalation or unintended access to resources."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc3-passrole-user-attach-policy" {
  user       = aws_iam_user.fn1-privesc3-partial-user.name
  policy_arn = aws_iam_policy.fn1-passrole-limited.arn
}

resource "aws_iam_policy" "fn1-passrole-limited" {
  name        = "fn1-passrole-limited"
  description = "A more restrictive policy for PassRole"

  policy = <<EOT
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "iam:PassRole",
      "Resource": "arn:aws:iam::123456789012:role/specific-role-name"
    }
  ]
}
EOT
}
",
  "fix_summary": "Replaced the overly permissive IAM policy with a more restrictive one that limits the PassRole action to a specific role."
}
